#pragma once

// Entry checks of stxlib::stx_minmallocpp, generated by tools/ic_declarations.py from
// src/state/stx_minmallocpp/allocator.ic.toml; edit the declaration, not this file. Each predicate is one `requires`
// clause of the declaration, so the condition the header states and the check the code runs are one text
// (docs/ic_declarations.md in template_harness).

#include "state/stx_minmallocpp/layout.hpp"
#include "stxlib/types.hpp"

namespace stxlib::stx_minmallocpp::ic {

// stx_minmallocpp::allocate: power_of_two(alignment) and alignment <= alignment_limit and size <= largest_request; else
// returns null.
[[nodiscard]] constexpr bool admits_allocate(const usize size, const usize alignment) noexcept {
    const bool result = (alignment != 0 && (alignment & (alignment - 1)) == 0)
                     && (alignment <= alignment_limit)
                     && (size <= largest_request);
    return result;
}

} // namespace stxlib::stx_minmallocpp::ic
